(()=>{'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',book:'M4 3h13a3 3 0 0 1 3 3v16H6a3 3 0 0 1 0-6h14 M4 3v16',arrow:'M5 12h14 m-5-5 5 5-5 5',back:'M19 12H5 m5-5-5 5 5 5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',x:'m6 6 12 12 M18 6 6 18',menu:'M4 6h16 M4 12h16 M4 18h16',mail:'M3 5h18v14H3z m0 0 9 7 9-7',lock:'M5 11h14v10H5z M8 11V6a4 4 0 0 1 8 0v5',sliders:'M4 6h16 M4 18h16 M4 12h16 M8 3v6 M16 9v6 M10 15v6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const fmt=n=>Number.isInteger(n)?String(n):Number(n).toFixed(1);
const range=(a,b)=>Math.abs(a-b)<.001?fmt(a):`${fmt(a)}–${fmt(b)}`;
const compact=n=>n>=1e6?`$${fmt(n/1e6)}M`:n>=1000?`$${fmt(n/1000)}K`:`$${fmt(n)}`;
const money=r=>r?`${compact(r.low)}${r.low!==r.high?'–'+compact(r.high).slice(1):''}`:'Revenue to estimate';
const date=s=>s?new Date(s.slice(0,10)+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Not recorded';
const initial=s=>String(s).split(' ').map(x=>x[0]).slice(0,2).join('');
const reqId=()=>globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(16).slice(2);
let state=null,page='queue',selected=null,tab='discovery',query='',filter='all',owner='all',sort='default',busy=false,toastTimer;
const current=()=>state?.cases.find(c=>c.id===selected);
const badge=r=>`<span class="badge ${r==='Ready'?'ready':r==='Not ready'?'notready':r==='Active'?'ready':r==='Contacted'?'pending':'evidence'}"><i class="dot"></i>${esc(r)}</span>`;
const modeLabel=m=>m==='live'?'Live AI':'Demo text rules';
const provenance=x=>`<span class="provenance ${x?.mode==='live'?'live':''}">${icon(x?.mode==='live'?'spark':'sliders')}${modeLabel(x?.mode||state.mode)}</span>`;
const field=(label,id,value='',type='text')=>`<div class="form-field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''}></div>`;
const empty=text=>`<div class="empty">${icon('file')}<br>${text}</div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div><div class="panel-body">${body}</div></section>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}
function modal(title,description,body,footer='',wide=false){const d=$('#dialog');d.classList.toggle('wide',wide);d.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${description}</p></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body"><div id="form-error" class="error-box" role="alert" hidden></div>${body}</div><div class="modal-footer">${footer}</div>`;if(!d.open)d.showModal()}
function close(){if(!busy)$('#dialog').close()}
function showError(e){const box=$('#form-error');if($('#dialog').open&&box){box.hidden=false;box.textContent=e.message}else toast(e.message)}
function setBusy(value,label='Working…'){busy=value;document.body.classList.toggle('working',value);document.querySelectorAll('#dialog button,#dialog input,#dialog select,#dialog textarea').forEach(el=>{if(value){el.dataset.wasDisabled=el.disabled?'1':'0';el.disabled=true}else if(el.dataset.wasDisabled!==undefined){el.disabled=el.dataset.wasDisabled==='1';delete el.dataset.wasDisabled}});const status=$('#busy-status');if(status){status.hidden=!value;status.textContent=label}}
async function api(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(body)});const result=await response.json();if(!response.ok){const e=new Error(result.error||'Request failed.');e.status=response.status;throw e}return result.result}
async function refresh(){const response=await fetch('/api/bootstrap',{cache:'no-store'});if(!response.ok)throw new Error('The local backend is unavailable. Start server.py and reload.');state=await response.json();render()}
async function mutate(path,body,message,keep=false){const result=await api(path,body);await refresh();if(!keep)$('#dialog').close();if(message)toast(message);return result}
function go(p){page=p;selected=null;render();window.scrollTo(0,0)}
function openCase(id,t){selected=id;page='case';const c=current();tab=t||(c.stage==='Contacted'?'prepare':'discovery');render();window.scrollTo(0,0)}
function unresolvedSources(c){const latest=new Map();for(const r of c.analysisRuns.slice().reverse())latest.set(r.sourceId,r);return [...latest.values()].filter(r=>['Failed','Running'].includes(r.status)&&!c.sources.find(s=>s.id===r.sourceId)?.manualReview).length}
function pending(c){return c.analysisRuns.reduce((n,r)=>n+r.proposals.filter(p=>p.status==='Pending').length,0)}
function nextFor(c){if(pending(c))return 'Review pending evidence suggestions';if(unresolvedSources(c))return 'Resolve or manually review the saved source';if(c.stage==='Contacted')return 'Prepare an introduction and record the reply';if(c.blocker)return 'Agree a future review trigger';if(c.result.readiness==='Ready')return 'Review the qualification pack';return c.result.gaps[0]?.label||'Validate the next milestone'}
function render(){if(!state)return;const focused=document.activeElement?.id,pos=document.activeElement?.selectionStart;$('#app').innerHTML=shell();if(focused==='search'){$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos)}}
function shell(){const names={queue:'Work queue',case:'Case workspace',followups:'Follow-ups',approvals:'Approvals',guide:'Scoring guide',settings:'Workspace settings'};const approvalCount=state.cases.filter(c=>['Submitted','Exception requested'].includes(c.approval?.status)).length;return `<div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><strong>CGS</strong></div><div class="brand-sub">Qualification workspace</div><nav class="nav" aria-label="Main navigation">${[['queue','grid','Work queue',state.cases.length],['followups','clock','Follow-ups',state.reminders.length],['approvals','file','Approvals',approvalCount],['guide','book','Scoring guide',''],['settings','sliders','Settings & agents','']].map(([p,i,l,n])=>`<button data-nav="${p}" class="${page===p||page==='case'&&p==='queue'?'active':''}">${icon(i)}${l}${n!==''?`<span class="count">${n}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-card"><strong>${icon('lock')} Saved to this workspace</strong><p>SQLite storage · local backend<br>${state.mode==='live'?'Live API mode selected':'Demo text rules selected'}</p><button data-nav="settings">Connection settings ${icon('arrow')}</button></div><div class="profile"><span class="avatar">AM</span><div><b>Local workspace</b><small>Consultant & reviewer preview</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button>Workspace <span>/</span><b>${names[page]}</b></div><div class="top-actions"><span class="top-date">${date(state.today)} · ${state.clock==='demo'?'demo clock':'system date'}</span><button class="mode-switch ${state.mode==='live'?'is-live':''}" data-nav="settings"><i class="dot"></i>${modeLabel(state.mode)}</button><span class="saved-indicator">${icon('check')} Database connected</span></div></header><div class="content">${state.mode==='live'&&!state.config.liveConfigured?'<div class="error-box">Live mode selected, but server credentials are incomplete. Configure .env in the source folder and restart the backend. Live requests will show an error; they never switch to demo results.</div>':''}${page==='queue'?queue():page==='case'?casePage():page==='followups'?followups():page==='approvals'?approvals():page==='guide'?guide():settings()}<footer class="page-note"><span>${icon('lock')} Local functional prototype · ${state.mode==='demo'?'demo text rules':'live API mode'} · no email or CRM writes</span><span>AI recommends. Consultants confirm. People approve.</span></footer></div></main></div><div id="busy-status" class="busy-status" role="status" hidden></div>`}
function queue(){let cases=state.cases.filter(c=>(!query||`${c.company} ${c.project} ${c.contact}`.toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||(filter==='pending'?pending(c)>0:c.result.readiness===filter))&&(owner==='all'||c.owner===owner));if(sort==='priority')cases.sort((a,b)=>a.revenue&&b.revenue?b.result.pl-a.result.pl:a.revenue?-1:b.revenue?1:0);const active=state.cases.filter(c=>c.stage==='Active').length,ready=state.cases.filter(c=>c.stage==='Active'&&c.result.readiness==='Ready').length,p=state.cases.reduce((n,c)=>n+pending(c),0);const focus=state.cases.find(c=>pending(c))||state.cases.find(c=>c.result.gaps.some(g=>g.key==='A'))||state.cases[0];return `<div class="page-heading"><div><div class="eyebrow">CONSULTANT WORKSPACE · STEPS 5–7</div><h1>Turn conversations into clear next steps.</h1><p class="subtitle">Evidence, commercial potential and readiness — together in one place.</p></div><div class="heading-actions"><button class="btn" data-action="export">${icon('download')} Export queue</button><button class="btn primary" data-action="new-case">${icon('plus')} Add a case</button></div></div><div class="stats">${[[active,'Active cases','Client reply received'],[p,'Suggestions to review','Human confirmation needed'],[ready,'Ready for approval','Qualification rules met'],[state.reminders.length,'Follow-up reminders','Backend monitored']].map(([n,t,d])=>`<div class="stat"><div class="stat-label">${t}</div><div class="stat-value">${n}</div><small>${d}</small></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Opportunity queue <span>${cases.length} cases</span></h2><span class="subtle-link">Proposed rules · ${esc(state.ruleVersion)}</span></div><div class="filters"><div class="search">${icon('search')}<label class="sr-only" for="search">Search cases</label><input id="search" placeholder="Search company, project or contact…" value="${esc(query)}"></div><select id="filter" aria-label="Readiness filter">${[['all','All readiness'],['pending','Suggestions pending'],['Ready','Ready'],['More evidence needed','Evidence needed'],['Not ready','Not ready']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select><select id="owner-filter" aria-label="Owner"><option value="all">All owners</option>${[...new Set(state.cases.map(c=>c.owner))].map(o=>`<option ${owner===o?'selected':''}>${esc(o)}</option>`).join('')}</select><select id="sort" aria-label="Sort queue"><option value="default">Default order</option><option value="priority" ${sort==='priority'?'selected':''}>Priority · known revenue</option></select></div><div class="table-wrap"><table class="queue"><thead><tr><th>Opportunity</th><th>Stage / readiness</th><th>Priority</th><th>CGS revenue</th><th>Next action</th></tr></thead><tbody>${cases.map((c,i)=>{let r=c.result;return `${sort==='priority'&&!c.revenue&&(i===0||cases[i-1].revenue)?'<tr class="group-row"><td colspan="5">Revenue to estimate · these cases are not ranked as low-revenue opportunities</td></tr>':''}<tr><td><button class="case-link" data-case="${c.id}">${esc(c.company)}</button><span class="cell-sub">${esc(c.project)}</span><span class="cell-sub">${esc(c.owner)} ${c.sample?'· sample case':''}</span></td><td><span class="stage-label">${c.stage}</span>${badge(r.readiness)}${c.blocker?`<span class="cell-sub warning-text">${esc(state.rules.reasons[c.blocker])}</span>`:''}</td><td><span class="priority ${r.priority==='High'?'high':''}">${esc(r.priority==='Pending confirmation'?'Pending':r.priority)}</span><span class="cell-sub">P ${range(r.pl,r.pu)}</span></td><td><span class="money">${money(c.revenue)}</span><span class="cell-sub">${c.revenue?(r.rt?'Tier '+r.rt:'Tier range')+' · first 12 months':'Not revenue-ranked'}</span></td><td><button class="text-action" data-case="${c.id}">${esc(nextFor(c))}</button>${pending(c)?`<span class="cell-sub">${pending(c)} suggestion(s) pending</span>`:''}</td></tr>`}).join('')||'<tr><td colspan="5">'+empty('No matching cases. Try a different filter.')+'</td></tr>'}</tbody></table></div></section><aside class="side-stack dashboard-side">${focus?`<section class="panel insight insight-highlight"><span class="ai-label">${icon('spark')} YOUR NEXT REVIEW</span><h3>${esc(focus.company)}</h3><p>${esc(nextFor(focus))}. Open the case to review the evidence and choose your next action.</p><button class="btn" data-case="${focus.id}">Open workspace ${icon('arrow')}</button></section>`:''}<section class="panel insight"><div class="eyebrow">HOW IT WORKS</div><h3>Capture. Confirm. Decide.</h3><p>Add a client email or meeting note. Review each supported suggestion. Confirmed evidence updates the assessment.</p><button class="btn" data-case="cedar" data-tab="discovery">Try a sample conversation</button></section><section class="panel insight"><div class="eyebrow">CGS POLICY</div><h3>A reply means Active.</h3><p>Readiness is a separate assessment. A high revenue estimate or a courtesy reply cannot qualify a case by itself.</p></section></aside></div>`}
function metrics(c){const r=c.result;return `<div class="assessment-metrics"><section class="metric-card"><span>QUALIFICATION · Q</span><b>${range(r.ql,r.qu)}<small>/ 100</small></b><p>${r.coverage}% of weighted dimensions confirmed</p><div class="progress"><i style="width:${r.coverage}%"></i></div>${r.ql!==r.qu?'<small class="metric-hint">Range reflects pending evidence, not an achieved upper score.</small>':''}</section><section class="metric-card"><span>CGS REVENUE POTENTIAL</span><b class="revenue-value">${money(c.revenue)}</b><p>${c.revenue?`R ${range(r.rl,r.ru)} · ${r.rt?'Tier '+r.rt:'Cross-tier estimate'}`:'No assigned revenue tier or observed R'}</p><small class="metric-hint">USD · first 12 months · demonstration assumptions</small><button class="link-button" data-action="revenue">Review estimate ${icon('arrow')}</button></section><section class="metric-card"><span>COMMERCIAL PRIORITY · P</span><b>${range(r.pl,r.pu)}<small>/ 100</small></b><p>${esc(r.priority)}</p><small class="metric-hint">60% qualification + 40% revenue. Readiness gates apply separately.</small></section></div>`}
function casePage(){const c=current();if(!c)return empty('Case not found.');const tabs=[['prepare','5','Prepare & contact','Draft and record outreach'],['discovery','6','Explore & capture','Analyze and review evidence'],['assessment','7','Assess readiness','Confirm gaps and next steps']];return `<button class="back" data-nav="queue">${icon('back')} Back to work queue</button><div class="page-heading case-header"><div class="case-title"><div class="case-logo">${initial(c.company)}</div><div><h1>${esc(c.company)}</h1><div class="case-sub">${esc(c.project)} <span>· ${esc(c.owner)}</span>${badge(c.stage)}${c.sample?'<span class="sample-label">SAMPLE CASE</span>':''}</div></div></div><div class="heading-actions"><button class="btn" data-action="pack">${icon('file')} Qualification pack</button><button class="btn primary" data-action="add-evidence">${icon('plus')} Add evidence</button></div></div><div class="workflow-nav" role="navigation" aria-label="Qualification workflow">${tabs.map(([id,n,title,desc])=>`<button class="workflow-step ${tab===id?'active':''}" data-tab="${id}"><b>${n}</b><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="tabs"><button data-tab="${['prepare','discovery','assessment'].includes(tab)?tab:'discovery'}" class="${['prepare','discovery','assessment'].includes(tab)?'active':''}">Current step</button><button data-tab="evidence" class="${tab==='evidence'?'active':''}">Evidence & sources <span>${c.evidence.length}</span></button><button data-tab="tasks" class="${tab==='tasks'?'active':''}">Tasks & history</button></div>${metrics(c)}<div class="detail-grid"><div class="side-stack case-main">${tab==='prepare'?preparePage(c):tab==='discovery'?discoveryPage(c):tab==='assessment'?assessmentPage(c):tab==='evidence'?evidencePage(c):tasksPage(c)}</div><aside class="side-stack">${readinessPanel(c)}${actionPanel(c)}</aside></div>`}
function readinessPanel(c){const r=c.result;return `<section class="panel readiness-box"><div class="eyebrow">READINESS RECOMMENDATION</div>${badge(r.readiness)}<h3>${r.readiness==='Ready'?'Ready for a human review':c.blocker?'Record the reason and review trigger':'Build the evidence before qualifying'}</h3><p>${c.blocker?esc(state.rules.reasons[c.blocker]):r.readiness==='Ready'?'The confirmed assessment meets the proposed rules. Final qualification requires human approval.':'Pending information stays pending. Confirm the key facts and resolve material conflicts.'}</p>${c.blocker?`<div class="reason-code">${esc(c.blocker)}</div>`:''}<ul class="gap-list">${r.gaps.slice(0,5).map(g=>`<li>${esc(g.label)}</li>`).join('')}</ul><button class="btn ${r.readiness==='Ready'?'primary':''}" data-action="${r.readiness==='Ready'?'pack':'conditions'}">${r.readiness==='Ready'?'Review qualification pack':'Review qualification conditions'}</button>${c.approval?`<div class="tagline">Approval: ${esc(c.approval.status)}${c.approval.outdated?' · earlier assessment; review again':''}${c.approval.version!==c.revision&&['Submitted','Exception requested'].includes(c.approval.status)?' · snapshot needs updating':''}</div>`:''}</section>`}
function actionPanel(c){const advice=c.advice;const stale=advice&&advice.baseRevision!==c.revision;return `<section class="panel insight"><span class="ai-label">${icon('spark')} NEXT BEST ACTIONS</span><h3>A useful next conversation.</h3><p>Suggested actions become tasks only after you confirm the owner and date.</p>${advice?`${provenance(advice)}${stale?'<p class="notice">The case changed. Refresh these suggestions before relying on them.</p>':''}${advice.actions.map((a,i)=>`<div class="action-card"><strong>${esc(a.title)}</strong><p>${esc(a.reason)}</p><blockquote>${esc(a.question)}</blockquote><button class="link-button" data-action="suggested-task" data-index="${i}">Review as a task ${icon('arrow')}</button></div>`).join('')}`:'<div class="tagline">Generate recommendations from the current confirmed assessment.</div>'}<button class="btn" data-action="generate-actions">${icon('spark')} ${advice?'Refresh suggestions':'Suggest next actions'}</button></section>`}
function preparePage(c){const draft=c.outreach;return panel('5 · Prepare and contact',`<div class="responsibility"><span><b>Human</b> Reviews, edits and sends</span><span><b>Assistant</b> Suggests approach and draft</span></div><p class="description">Use the contact’s context to open a conversation. Unverified needs remain questions.</p><div class="field-grid"><div class="field"><label>Client contact</label><p>${esc(c.contact)} · ${esc(c.role)}</p></div><div class="field"><label>Discovery topic</label><p>${esc(c.project)}</p></div></div><div class="section-gap"><button class="btn primary" data-action="generate-outreach">${icon('spark')} ${draft?'Regenerate outreach draft':'Generate outreach draft'}</button></div>${draft?`<div class="section-gap">${provenance(draft)}<p class="description">${esc(draft.approach)}</p><div class="form-field section-gap"><label for="saved-subject">Suggested subject</label><input id="saved-subject" value="${esc(draft.subject)}"></div><div class="form-field"><label for="saved-draft">Editable draft</label><textarea id="saved-draft" class="draft-text">${esc(draft.draft)}</textarea></div><div class="heading-actions"><button class="btn primary" data-action="save-draft">Save edited draft</button><button class="btn" data-action="copy-draft">Copy edited draft</button></div><p class="tagline">Save your edits before leaving this step. Copy the draft for sending through your normal email tool; nothing is emailed here.</p><div class="section-label">Suggested questions</div>${draft.questions.map(q=>`<p class="description">• ${esc(q)}</p>`).join('')}</div>`:''}`)+panel('Record the client’s reply',`<p class="description">Any recorded client reply makes this case Active under CGS policy. Evidence scoring is reviewed separately.</p><div class="section-gap"><button class="btn" data-action="record-reply">${icon('mail')} Record reply & analyze</button></div>`)}
function discoveryPage(c){const runs=c.analysisRuns;return panel('6 · Engage and explore need',`<div class="responsibility"><span><b>Human</b> Leads discovery and verifies findings</span><span><b>Assistant</b> Organizes facts and information gaps</span></div><p class="description">${esc(c.problem)}</p><div class="capture-callout"><div>${icon('file')}<strong>Start with what the client actually said.</strong><p>Paste an email or meeting note. One source can support several qualification dimensions.</p></div><button class="btn primary" data-action="add-evidence">Analyze a new note ${icon('arrow')}</button></div>${state.mode==='demo'?'<p class="notice">Demo mode uses conservative English text patterns. You can edit the text freely; no scenario controls the result. Use Live AI for general language analysis.</p>':''}`, '<button class="btn tiny" data-action="problem">Review problem summary</button>')+panel(`Evidence analysis <span class="subtle-link">${runs.length} run(s)</span>`,runs.length?runs.map(r=>`<article class="run-row"><div class="evidence-top"><strong>${esc(r.source)}</strong><span class="badge ${r.status==='Failed'?'notready':r.status==='Complete'?'ready':'evidence'}">${esc(r.status)}</span></div>${provenance(r)}<p>${esc(r.error||r.summary||'Analysis in progress. Refresh this page to check the result.')}</p><div class="evidence-meta"><span>${date(r.createdAt)} · ${r.proposals.filter(p=>p.status==='Pending').length} pending</span><span>${r.calls?.length||0} live model call(s)</span></div><div class="run-actions"><button class="btn tiny" data-action="source" data-id="${r.sourceId}">View source</button>${r.status!=='Failed'&&r.proposals.length?`<button class="btn tiny primary" data-action="review-run" data-id="${r.id}">Review suggestions</button>`:''}${r.status!=='Running'?`<button class="btn tiny" data-action="reanalyze" data-id="${r.sourceId}">Re-analyze saved source</button>`:'<button class="btn tiny" data-action="refresh">Refresh status</button>'}</div></article>`).join(''):empty('No analysis yet. Add a note to begin.'))}
function assessmentPage(c){const {weights,labels,anchors}=state.rules;return panel('7 · Assess qualification readiness',`<div class="responsibility"><span><b>Human</b> Confirms ratings and qualification evidence</span><span><b>Assistant</b> Explains gaps and prepares recommendations</span></div><p class="description">Q = Σ(weight × confirmed score ÷ 5). Unknown dimensions contribute an uncertainty interval. Each rating remains editable with evidence and a reason.</p>`)+`<section class="panel"><div class="panel-head"><h2>BANTHE evidence review</h2><span class="subtle-link">${pending(c)} pending suggestion(s)</span></div>${Object.keys(weights).map(k=>{const v=c.scores[k],ev=c.evidence.filter(e=>e.dimension===k).slice(-2);return `<details class="dimension"><summary><span class="dim-letter">${k}</span><span><strong>${labels[k]}</strong><small>${weights[k]}% weight · ${v===null?'Pending confirmation':v===2.5?'Confirmed first-time relationship':esc(anchors[k][v])}</small></span><b>${v===null?'Pending':fmt(v)+' / 5'}</b></summary><div class="dimension-body">${ev.map(e=>`<blockquote>${esc(e.quote)}</blockquote><div class="tagline">${esc(e.source)} · ${date(e.date)} · ${esc(e.origin||'Sample data')}</div>`).join('')||'<p class="description">No confirmed evidence for this dimension.</p>'}<p class="tagline">${v===null?'No score has been assigned.':v===2.5?'Neutral rule: confirmed first project together.':'Rubric anchor: '+esc(anchors[k][v])}</p><button class="btn tiny" data-action="score" data-dim="${k}">Review rating</button></div></details>`}).join('')}</section>`+panel('Qualification conditions',conditionsHTML(c),'<button class="btn tiny" data-action="conditions">Review conditions</button>')+panel('What changed?',versionsHTML(c,3),'<button class="link-button" data-tab="tasks">Full history</button>')}
function conditionsHTML(c){return Object.entries(state.rules.conditionLabels).map(([k,l])=>`<div class="condition ${c.conditions[k]===null?'pending':c.conditions[k]===false?'failed':''}">${icon(c.conditions[k]===true?'check':'alert')}<span>${esc(l)}</span><span class="state">${c.conditions[k]===true?'Confirmed':c.conditions[k]===false?'Not met':'Pending'}</span></div>`).join('')}
function evidencePage(c){return panel('Original sources',c.sources.length?c.sources.map(s=>`<div class="source-row"><div><strong>${esc(s.source)}</strong><p>${esc(s.kind)} · ${date(s.date)}</p></div><button class="btn tiny" data-action="source" data-id="${s.id}">Open source</button></div>`).join(''):empty('Imported sources will appear here.'),'<button class="btn tiny" data-action="add-evidence">Add source</button>')+panel('Confirmed evidence',c.evidence.length?`<div class="evidence-list">${c.evidence.slice().reverse().map(e=>`<article class="evidence-item"><div class="evidence-top"><strong>${esc(state.rules.labels[e.dimension]||state.rules.conditionLabels[e.dimension?.split(':')[1]]||e.dimension)}</strong><span class="badge ready">Human confirmed</span></div><blockquote>${esc(e.quote)}</blockquote><p class="description">${esc(e.interpretation)}</p>${e.reviewReason?`<p class="tagline">Review rationale: ${esc(e.reviewReason)}</p>`:''}<div class="evidence-meta"><span>${esc(e.source)} · ${date(e.date)}</span><span>${esc(e.origin||'Sample data')}</span></div>${e.sourceId?`<button class="link-button section-gap" data-action="source" data-id="${e.sourceId}">Open original source</button>`:''}</article>`).join('')}</div>`:empty('Confirmed findings will appear after review.'))}
function versionsHTML(c,limit=100){return c.versions.slice().reverse().slice(0,limit).map(v=>`<article class="version-card"><div class="evidence-top"><strong>${esc(v.title)}</strong><small>${date(v.date)}</small></div><p>${esc(v.detail)}</p>${v.before?`<div class="change-metrics"><span>Q <b>${range(v.before.ql,v.before.qu)} → ${range(v.after.ql,v.after.qu)}</b></span><span>P <b>${range(v.before.pl,v.before.pu)} → ${range(v.after.pl,v.after.pu)}</b></span><span>Readiness <b>${esc(v.before.readiness)} → ${esc(v.after.readiness)}</b></span></div>`:`<p class="tagline">Q ${range(v.after.ql,v.after.qu)} · P ${range(v.after.pl,v.after.pu)}</p>`}<small class="tagline">${esc(v.ruleVersion||'1.0 sample baseline')}</small></article>`).join('')||empty('No assessment versions yet.')}
function tasksPage(c){return panel('Agreed next actions',c.tasks.length?c.tasks.map(t=>`<div class="task ${t.status==='Done'?'done':''}"><button class="task-check" data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button><div class="task-main"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${esc(t.side)} · ${esc(t.assignee)} · ${date(t.due)} ${t.status==='Open'&&t.due<state.today?'<span class="warning-text">· Overdue</span>':''}</div></div><button class="btn tiny" data-action="reschedule" data-id="${t.id}">Reschedule</button></div>`).join(''):empty('No agreed actions recorded.'),'<button class="btn tiny" data-action="new-task">Add agreed action</button>')+panel('Assessment versions',versionsHTML(c))+panel('Activity record',`<div class="timeline">${c.events.map(e=>`<article class="event"><small>${date(e.date)}</small><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></article>`).join('')}</div>`)}
function followups(){return `<div class="page-heading"><div><div class="eyebrow">BACKGROUND MONITOR</div><h1>Keep the next step moving.</h1><p class="subtitle">The server checks every 30 seconds while running, even when the browser is closed. No automatic score deductions.</p></div><button class="btn" data-action="refresh">Refresh reminders</button></div><section class="panel">${state.reminders.map(r=>`<article class="alert-row"><div class="alert-icon">${icon('clock')}</div><div class="alert-main"><h3>${esc(r.company)} · ${esc(r.title)}</h3><p>${esc(r.reason)}</p><span class="tagline">${esc(r.type)}</span></div><div class="alert-actions"><button class="btn tiny" data-case="${r.caseId}" data-tab="tasks">Open case</button><button class="btn tiny" data-action="snooze" data-id="${r.id}">Snooze 7 days</button></div></article>`).join('')||empty('No overdue or stalled cases need attention.')}</section><p class="tagline">Last backend check: ${esc(state.config.lastScan)} · 14-day progress window is a prototype configuration.</p>`}
function approvals(){const cases=state.cases.filter(c=>c.approval);return `<div class="page-heading"><div><div class="eyebrow">STEP 8 · HUMAN DECISION</div><h1>Review the evidence, then decide.</h1><p class="subtitle">Local reviewer preview. Approval does not create an Insightly opportunity.</p></div></div><section class="panel">${cases.map(c=>`<article class="approval-record"><div class="approval-main"><h3>${esc(c.company)}</h3><p>${esc(c.project)} · submitted ${date(c.approval.date)}<br>${esc(c.approval.status)}${c.approval.version!==c.revision&&['Submitted','Exception requested'].includes(c.approval.status)?' · changed since submission':''}</p></div><button class="btn" data-action="review-approval" data-case-id="${c.id}">Review frozen pack</button></article>`).join('')||empty('Ready cases appear here after submission.')}</section>`}
function guide(){return `<div class="page-heading"><div><h1>The evidence behind the score.</h1><p class="subtitle">Proposed settings for CGS validation · ${esc(state.ruleVersion)}</p></div></div><div class="rules-summary">${panel('Qualification and priority','<div class="formula">Q = Σ(weight × score / 5)</div><div class="formula">P = 0.6Q + 0.4R</div><p class="description">Unknown values remain null. Q and P retain lower–upper bounds. Revenue unknown has no tier and no observed R. First-time H=2.5 requires explicit confirmation.</p>')}${panel('Ready requires every gate','<p class="description">Q lower bound ≥70, coverage ≥80%, B≥2, A≥2, N≥3, T≥2 and E≥2, all six qualification conditions confirmed, and no explicit blocker. These five mandatory dimensions together carry 95% weight; 80% coverage cannot bypass a missing mandatory dimension.</p>')}</div><div class="guide-grid">${Object.entries(state.rules.anchors).map(([k,items])=>panel(`${k} · ${state.rules.labels[k]} <span class="subtle-link">${state.rules.weights[k]}%</span>`,items.map((s,i)=>`<div class="guide-line"><b>${i}</b><span>${esc(s)}</span></div>`).join('')+(k==='H'?'<div class="notice">2.5: explicitly confirmed first project together. Missing history remains pending.</div>':''))).join('')}</div><div class="section-gap">${panel('CGS fee revenue tiers','<table class="guide-table"><thead><tr><th>Tier</th><th>First 12 months · USD</th><th>R</th></tr></thead><tbody><tr><td>5</td><td>≥ $1M</td><td>100</td></tr><tr><td>4</td><td>$500K to &lt;$1M</td><td>80</td></tr><tr><td>3</td><td>$100K to &lt;$500K</td><td>60</td></tr><tr><td>2</td><td>Below $100K</td><td>40</td></tr><tr><td>Unassigned</td><td>Revenue to estimate</td><td>Pending</td></tr></tbody></table>')}</div>`}
function settings(){return `<div class="page-heading"><div><div class="eyebrow">LOCAL PROTOTYPE · CONNECTIONS & RESPONSIBILITIES</div><h1>A clear boundary between demo and live.</h1><p class="subtitle">API secrets stay on the server. A live error never becomes a simulated success.</p></div></div><div class="guide-grid">${panel('Analysis mode',`<div class="form-field"><label for="mode-setting">Provider mode</label><select id="mode-setting"><option value="demo" ${state.mode==='demo'?'selected':''}>Demo · deterministic text rules</option><option value="live" ${state.mode==='live'?'selected':''}>Live · OpenAI Responses API</option></select><small>Demo recognizes a limited set of English statements. Live mode uses the configured model for arbitrary notes.</small></div><div class="data-line"><span>Live configuration</span><b>${state.config.liveConfigured?'Server credentials configured':'Not configured'}</b></div><div class="data-line"><span>Model</span><b>${esc(state.config.model||'Set OPENAI_MODEL')}</b></div><p class="notice">To connect: copy .env.example to .env beside server.py, set OPENAI_API_KEY and OPENAI_MODEL, restart the server, then select Live mode. No key is stored in browser storage.</p><button class="btn primary" data-action="save-mode">Save mode</button>`)}${panel('Storage and integrations',`<div class="data-line"><span>Persistence</span><b>SQLite database · server-side</b></div><div class="data-line"><span>Email ingestion</span><b>Manual paste / .txt import</b></div><div class="data-line"><span>Insightly</span><b>Not connected</b></div><div class="data-line"><span>Identity</span><b>Single local workspace</b></div><p class="description section-gap">Consultant and reviewer actions are functional local records. Production role-based authentication and external CRM/mail adapters remain future integration work.</p>`)}${panel('Four bounded assistant roles',`<div class="agent-row"><b>A1 · Preparation & outreach</b><span>Confirmed context → editable contact draft</span></div><div class="agent-row"><b>A2 · Evidence & engagement</b><span>Original source → exact-quote findings</span></div><div class="agent-row"><b>A3 · Qualification advisory</b><span>Findings + rubric → reviewable suggestions</span></div><div class="agent-row"><b>A4 · Action & reporting</b><span>Confirmed assessment → up to 3 suggested actions</span></div><p class="tagline">The backend coordinates these roles. Fixed rules calculate Q, R, P and readiness. Qualification packs use the confirmed snapshot.</p>`)}${panel('Demonstration clock',`<div class="form-field"><label for="clock-setting">Time source</label><select id="clock-setting"><option value="demo" ${state.clock==='demo'?'selected':''}>Demo date</option><option value="system" ${state.clock==='system'?'selected':''}>System date</option></select></div>${field('Demo date','clock-date',state.today,'date')}<button class="btn" data-action="save-clock">Save clock</button><p class="tagline">Reminders are stored by the backend. The backend must remain running for background checks.</p><div class="section-gap"><button class="btn danger" data-action="reset">Reset sample workspace</button><p class="tagline">Explicit reset removes cases, imported sources and reviews from this local workspace. It restores the seven demonstration cases.</p></div>`)}</div>`}
const samples={budget:'Our project budget is approved and covers the initial scope. We shared the requested process maps.',authority:'Our CFO is joining the next discussion as the key decision-maker. We are open to external consulting support.',courtesy:'Thank you for sending this through. I have received the introduction.',blocker:'We are not considering external consulting support for this project.'};
function evidenceModal(kind='Meeting notes'){modal('Capture a conversation','Record the original source, then review every suggested change.',`<p class="notice">Client reply → Active immediately. Scores change only after human confirmation. ${state.mode==='demo'?'Demo uses limited English text patterns.':'Live mode sends this source and the case context to the configured model.'}</p><div class="form-row"><div class="form-field"><label for="source-kind">Evidence type</label><select id="source-kind">${['Client reply','Meeting notes','Relationship record','Other evidence'].map(x=>`<option ${kind===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Evidence date','evidence-date',state.today,'date')}</div>${field('Source label','source-label','','text')}<div class="form-field"><label for="note">Original email or meeting note</label><textarea id="note" class="note-input" placeholder="Paste the client’s original words here…" maxlength="16000"></textarea><small>Up to 16,000 characters. Keep facts, future promises and your own interpretation distinguishable.</small></div><div class="sample-tools"><label class="btn tiny file-label">Import .txt<input id="text-file" type="file" accept=".txt,text/plain" class="sr-only"></label><span>Load sample text:</span>${Object.keys(samples).map(k=>`<button class="btn tiny" data-action="sample-text" data-id="${k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><p class="tagline">Samples only fill the text box. The entered text determines the analysis.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="analyze">${icon('spark')} Save source & analyze</button>`,true)}
function sourceModal(id){const c=current(),s=c.sources.find(s=>s.id===id);if(!s)return toast('Source not found.');modal('Original source',`${esc(s.source)} · ${esc(s.kind)} · ${date(s.date)}`,`<div class="source-original">${esc(s.text)}</div><p class="tagline">Source ID: ${esc(s.id)} · Stored ${esc(s.createdAt)}</p>${s.manualReview?`<p class="notice">Manually reviewed by ${esc(s.manualReview.reviewer)}. ${esc(s.manualReview.reason)}</p>`:""}`,`<button class="btn" data-action="manual-source" data-id="${id}">Record manual review</button><button class="btn" data-action="close">Close</button><button class="btn primary" data-action="reanalyze" data-id="${id}">Re-analyze this source</button>`,true)}
function targetLabel(p){return state.rules.labels[p.target]||state.rules.conditionLabels[p.target.split(':')[1]]||(p.target==='blocker'?'Not ready reason':p.target)}
function proposalValue(p){return p.target in state.rules.weights?(p.score===null?'Pending':p.score+' / 5'):p.target.startsWith('condition:')?(p.condition_value?'Confirmed':'Not met'):state.rules.reasons[p.blocker_code]}
function oldValue(c,p){return p.target in state.rules.weights?(c.scores[p.target]===null?'Pending':c.scores[p.target]+' / 5'):p.target.startsWith('condition:')?(c.conditions[p.target.split(':')[1]]===null?'Pending':c.conditions[p.target.split(':')[1]]?'Confirmed':'Not met'):(state.rules.reasons[c.blocker]||'No blocker')}
function scoreOptions(k,value){return `<option value="" ${value===null?'selected':''}>Pending confirmation</option>${[0,1,2,...(k==='H'?[2.5]:[]),3,4,5].map(v=>`<option value="${v}" ${value===v?'selected':''}>${v} · ${v===2.5?'Confirmed first-time relationship':esc(state.rules.anchors[k][v])}</option>`).join('')}`}
function reviewRun(id){const c=current(),r=c.analysisRuns.find(r=>r.id===id);if(!r)return toast('Analysis not found.');const stale=r.baseRevision!==c.revision;modal('Review evidence suggestions','Confirm the original statement and proposed interpretation separately.',`${provenance(r)}<p class="description section-gap">${esc(r.summary||r.error||'Analysis pending.')}</p>${stale?'<div class="error-box">This analysis predates changes to the case. Re-analyze the saved source before applying pending suggestions.</div>':''}${r.proposals.map(p=>{const f=r.findings.find(f=>f.id===p.finding_id),active=p.status==='Pending'&&!stale;return `<article class="proposal-card" id="proposal-${p.id}"><div class="evidence-top"><strong>${esc(targetLabel(p))}</strong><span class="badge ${p.status==='Rejected'?'notready':p.status==='Pending'?'evidence':'ready'}">${esc(p.status)}</span></div><blockquote>${esc(f?.quote)}</blockquote><div class="source-caption">Exact quote verified · ${esc(r.source)} · ${date(r.date)}</div><div class="proposal-delta"><span>Current: ${esc(oldValue(c,p))}</span><strong>Suggested: ${esc(proposalValue(p))}</strong></div><p>${esc(p.explanation)}</p>${p.question?`<div class="suggested-question"><b>Useful follow-up</b><p>${esc(p.question)}</p></div>`:''}${p.conflict?'<p class="error-box">Potential evidence conflict. Explain your decision. Accepting keeps the conflict condition unresolved until a separate human review.</p>':''}${active?`<details class="edit-proposal"><summary>Edit the proposed value</summary>${p.target in state.rules.weights?`<div class="form-field"><label for="edit-${p.id}">Consultant rating</label><select id="edit-${p.id}">${scoreOptions(p.target,p.score)}</select></div>`:p.target.startsWith('condition:')?`<div class="form-field"><label for="edit-${p.id}">Reviewed condition</label><select id="edit-${p.id}"><option value="true" ${p.condition_value?'selected':''}>Confirmed</option><option value="false" ${!p.condition_value?'selected':''}>Not met</option><option value="pending">Pending confirmation</option></select></div>`:'<p class="tagline">To choose a different Not ready reason, reject this suggestion and use Review conditions.</p>'}</details><div class="form-field"><label for="reason-${p.id}">Review rationale ${p.conflict?'(required)':'(required for edits or rejection)'}</label><textarea id="reason-${p.id}" placeholder="Record evidence, a correction or a reason for rejecting…"></textarea></div><div class="proposal-actions"><button class="btn primary" data-action="proposal" data-run="${r.id}" data-pid="${p.id}" data-decision="Accept">Accept suggestion</button>${p.target!=='blocker'?`<button class="btn" data-action="proposal" data-run="${r.id}" data-pid="${p.id}" data-decision="Edit">Save edited value</button>`:''}<button class="btn danger" data-action="proposal" data-run="${r.id}" data-pid="${p.id}" data-decision="Reject">Reject</button></div>`:`<p class="tagline">${esc(p.reviewReason||'Consultant decision recorded.')}</p>`}</article>`}).join('')}${r.calls?.length?`<details class="run-trace"><summary>Model call trace · ${r.calls.length} calls</summary>${r.calls.map(x=>`<p>${esc(x.role)} · ${esc(x.model)}<br>Request: ${esc(x.requestId||'Unavailable')}<br>Response: ${esc(x.responseId||'Unavailable')}</p>`).join('')}</details>`:''}`,`<button class="btn" data-action="source" data-id="${r.sourceId}">View original source</button><button class="btn" data-action="close">Done</button>${stale?`<button class="btn primary" data-action="reanalyze" data-id="${r.sourceId}">Re-analyze source</button>`:''}`,true)}
function scoreModal(k){const c=current();modal('Review '+state.rules.labels[k],'Save a human judgement with its supporting evidence.',`<div class="form-field"><label for="score-value">Reviewed rating</label><select id="score-value">${scoreOptions(k,c.scores[k])}</select></div><div class="form-field"><label for="manual-reason">Evidence and rationale</label><textarea id="manual-reason" placeholder="Record the source and why this anchor applies…"></textarea></div>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-score" data-dim="${k}">Confirm rating</button>`)}
function revenueModal(){const c=current();modal('Review CGS revenue potential','Estimate CGS fees separately from client budget feasibility.',`<p class="notice">USD · first 12 months are demonstration assumptions pending CGS validation. Record a scope and fee basis; do not copy the client’s total project budget as CGS revenue.</p><div class="form-field"><label for="revenue-status">Estimate status</label><select id="revenue-status"><option value="known" ${c.revenue?'selected':''}>Estimated range</option><option value="pending" ${!c.revenue?'selected':''}>Revenue to estimate</option></select></div><div class="form-row">${field('Lower estimate · USD','revenue-low',c.revenue?.low??'','number')}${field('Upper estimate · USD','revenue-high',c.revenue?.high??'','number')}</div><div class="form-field"><label for="manual-reason">Scope, fee basis or reason pending</label><textarea id="manual-reason">${esc(c.revenue?.basis||'')}</textarea></div>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-revenue">Confirm estimate</button>`)}
function conditionsModal(){const c=current();modal('Review qualification conditions','Each condition needs human confirmation. Unknown is distinct from not met.',`${Object.entries(state.rules.conditionLabels).map(([k,l])=>`<div class="form-field"><label for="condition-${k}">${l}</label><select id="condition-${k}"><option value="pending" ${c.conditions[k]===null?'selected':''}>Pending confirmation</option><option value="true" ${c.conditions[k]===true?'selected':''}>Confirmed</option><option value="false" ${c.conditions[k]===false?'selected':''}>Not met</option></select></div>`).join('')}<div class="form-field"><label for="blocker">Explicit Not ready reason</label><select id="blocker"><option value="">No explicit blocker</option>${Object.entries(state.rules.reasons).map(([k,l])=>`<option value="${k}" ${c.blocker===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label for="manual-reason">Evidence and review rationale</label><textarea id="manual-reason" placeholder="Explain supporting evidence, conflict resolution or why a blocker can be cleared…"></textarea></div><p class="tagline">Missing information creates an evidence gap. Confirmed refusal of external support or service mismatch records a Not ready reason.</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-conditions">Confirm reviewed conditions</button>`,true)}
function taskModal(suggested){const c=current();modal('Confirm a next action','An assistant suggestion is not an agreed client commitment.',`${suggested?`<div class="notice">${esc(suggested.reason)}<br>Suggested question: ${esc(suggested.question)}</div>`:''}${field('Action','task-title',suggested?.title||'')}<div class="form-row">${field('Named owner','task-owner',c.owner)}<div class="form-field"><label for="task-side">Responsible party</label><select id="task-side"><option>CGS</option><option>Client</option></select></div></div>${field('Agreed due date','task-due','','date')}<label class="confirm-check"><input id="task-confirmed" type="checkbox"> I have confirmed the owner and agreed date.</label>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-task">Record agreed action</button>`)}
function packHTML(c,snapshot=null){const data=snapshot?.case||c,r=snapshot?.result||c.result;return `<div class="pack-mini"><b>${esc(data.company)}</b> · ${esc(data.project)}<br>Owner: ${esc(data.owner)} · ${esc(r.ruleVersion||state.ruleVersion)}<br>${badge(r.readiness)}</div><div class="pack-section"><h3>Client problem and impact</h3><p>${esc(data.problem)}</p></div><div class="pack-section"><h3>Commercial and qualification assessment</h3><p>Q: ${range(r.ql,r.qu)} · coverage ${r.coverage}%<br>CGS revenue: ${money(data.revenue)} · USD · first 12 months<br>P: ${range(r.pl,r.pu)} · ${esc(r.priority)}</p><p>${Object.entries(data.scores).map(([k,v])=>`${k}: ${v===null?'Pending confirmation':v}`).join(' · ')}</p>${data.blocker?`<p>Not ready: ${esc(state.rules.reasons[data.blocker])}</p>`:''}</div><div class="pack-section"><h3>Qualification conditions</h3>${conditionsHTML(data)}</div><div class="pack-section"><h3>Confirmed evidence</h3>${data.evidence.map(e=>`<p><b>${esc(e.dimension)} · ${esc(e.source)}</b><br>${esc(e.quote)}<br><small>${esc(e.origin||'Sample data')} · ${date(e.date)}</small></p>`).join('')||'<p>No confirmed evidence.</p>'}</div><div class="pack-section"><h3>Outstanding gaps</h3>${r.gaps?.map(g=>`<p>${esc(g.label)}</p>`).join('')||'<p>No qualification gaps recorded.</p>'}</div><div class="pack-section"><h3>Agreed actions</h3>${data.tasks.map(t=>`<p>${esc(t.title)} · ${esc(t.assignee)} · ${date(t.due)} · ${t.status}</p>`).join('')||'<p>No agreed actions.</p>'}</div>`}
function packModal(review=false){const c=current(),a=c.approval,pendingReview=review&&['Submitted','Exception requested'].includes(a.status),stale=pendingReview&&a.version!==c.revision,canSubmit=c.stage==='Active'&&c.result.readiness==='Ready'&&pending(c)===0&&unresolvedSources(c)===0&&(!a||['Returned','Deferred'].includes(a.status)||a.outdated);modal(review?'Review frozen qualification pack':'Qualification pack',review?'Human reviewer preview. Review the submitted snapshot before deciding.':'Review the confirmed evidence before submitting for human approval.',`${review&&stale?'<div class="error-box">The case changed after submission. Return the pack and request an updated submission; approval is unavailable.</div>':''}${review?`<p class="notice">Status: ${esc(a.status)}${a.outdated?' · historical decision; the current case needs reassessment.':''}${a.reason?'<br>Rationale: '+esc(a.reason):''}</p>`:''}${packHTML(c,review?a.snapshot:null)}${review&&pendingReview?'<div class="form-field"><label for="approval-reason">Reviewer rationale (required for return, defer or exception approval)</label><textarea id="approval-reason"></textarea></div>':''}${!review&&!canSubmit?'<p class="notice">Standard submission requires an Active case meeting every readiness gate, with all pending suggestions reviewed and failed analyses resolved or manually reviewed. An exception request records a separate human review and does not change readiness.</p>':''}`,`<button class="btn" data-action="export-pack" data-frozen="${review?'yes':'no'}">${icon('download')} Export pack</button>${review&&pendingReview?`<button class="btn" data-action="approval-decision" data-decision="return">Return for evidence</button><button class="btn" data-action="approval-decision" data-decision="defer">Defer</button><button class="btn primary" data-action="approval-decision" data-decision="approve" ${stale?'disabled':''}>Approve${a.status==='Exception requested'?' exception':''}</button>`:!review?`${!canSubmit&&(!a||['Returned','Deferred'].includes(a.status)||a.outdated)?'<button class="btn" data-action="exception">Request exception</button>':''}<button class="btn primary" data-action="submit-pack" ${!canSubmit?'disabled':''}>Submit for approval</button>`:'<button class="btn" data-action="close">Close</button>'}`,true)}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function handle(a,el){if(busy)return;let c=current();try{switch(a){
case'menu':$('#sidebar').classList.toggle('open');return;
case'close':close();return;
case'refresh':await refresh();toast('Workspace refreshed from the database.');return;
case'new-case':modal('Add an outreach case','Start with a contact and owner. Qualification evidence remains pending.',`${field('Company','new-company')}${field('Project or discovery topic','new-project')}${field('Client contact','new-contact')}${field('CGS owner','new-owner','Alex Morgan')}`,'<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="create-case">Create case</button>');return;
case'create-case':{setBusy(true,'Saving case…');const value=await mutate('/api/cases',{company:$('#new-company').value,project:$('#new-project').value,contact:$('#new-contact').value,owner:$('#new-owner').value},'Case created.');openCase(value.id,'prepare');return;}
case'add-evidence':evidenceModal();return;
case'record-reply':evidenceModal('Client reply');return;
case'sample-text':$('#note').value=samples[el.dataset.id];$('#source-label').value='Sample client email · demonstration';$('#source-kind').value='Client reply';return;
case'analyze':case'reanalyze':{const body=a==='reanalyze'?{sourceId:el.dataset.id}:{text:$('#note').value,source:$('#source-label').value,date:$('#evidence-date').value,kind:$('#source-kind').value};body.revision=c.revision;body.requestId=reqId();setBusy(true,'Saving source and analyzing evidence…');const run=await api(`/api/cases/${c.id}/analyze`,body);await refresh();tab='discovery';render();if(run.status==='Failed'){modal('Source saved · analysis failed','Scores remain unchanged. A recorded client reply still makes the case Active.',`<div class="error-box">${esc(run.error)}</div><p class="description">The original source is stored in Evidence & sources. Check the connection settings or retry explicitly.</p>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-action="reanalyze" data-id="${run.sourceId}">Retry saved source</button>`)}else if(run.proposals.length)reviewRun(run.id);else modal('Source saved · no supported changes','The source is retained. No qualification scores were changed.',`<p class="description">${esc(run.summary)}</p>`,'<button class="btn" data-action="close">Done</button>');return;}
case'source':sourceModal(el.dataset.id);return;
case'manual-source':modal('Record a manual source review','Use this when model analysis is unavailable. Review ratings and conditions separately before acknowledging the source.','<div class="form-field"><label for="manual-reason">What you verified and any assessment changes recorded</label><textarea id="manual-reason"></textarea></div><label class="confirm-check"><input id="source-reviewed" type="checkbox"> I reviewed this source and recorded any rating, condition or conflict changes separately.</label>',`<button class="btn" data-action="source" data-id="${el.dataset.id}">Back to source</button><button class="btn primary" data-action="save-source-review" data-id="${el.dataset.id}">Record manual review</button>`);return;
case'save-source-review':setBusy(true);await mutate(`/api/cases/${c.id}/review`,{revision:c.revision,kind:'source',sourceId:el.dataset.id,confirmed:$('#source-reviewed').checked,reason:$('#manual-reason').value},'Manual source review recorded. No scores changed automatically.');return;

case'review-run':reviewRun(el.dataset.id);return;
case'proposal':{const run=el.dataset.run,pid=el.dataset.pid,decision=el.dataset.decision,r=c.analysisRuns.find(r=>r.id===run),p=r.proposals.find(p=>p.id===pid);const body={revision:c.revision,proposalId:pid,decision,reason:$('#reason-'+pid).value};if(decision==='Edit'){const val=$('#edit-'+pid).value;if(p.target in state.rules.weights)body.score=val===''?null:Number(val);else body.conditionValue=val==='pending'?null:val==='true'}setBusy(true,'Recording consultant decision…');await mutate(`/api/runs/${run}/review`,body,'Review saved. Assessment and history updated.',true);reviewRun(run);return;}
case'score':scoreModal(el.dataset.dim);return;
case'save-score':{setBusy(true,'Saving reviewed rating…');const value=$('#score-value').value;await mutate(`/api/cases/${c.id}/review`,{revision:c.revision,kind:'score',dimension:el.dataset.dim,score:value===''?null:Number(value),reason:$('#manual-reason').value},'Rating saved with its evidence.');return;}
case'revenue':revenueModal();return;
case'save-revenue':{const known=$('#revenue-status').value==='known',low=$('#revenue-low').value,high=$('#revenue-high').value;if(known&&(low===''||high===''))throw new Error('Enter both revenue bounds or choose Revenue to estimate.');setBusy(true,'Saving revenue basis…');await mutate(`/api/cases/${c.id}/review`,{revision:c.revision,kind:'revenue',revenue:known?{low:Number(low),high:Number(high)}:null,reason:$('#manual-reason').value},'Revenue estimate saved.');return;}
case'problem':modal('Review the client problem summary','Keep the business problem clear without automatically confirming service fit.',`<div class="form-field"><label for="problem-summary">Client problem and business impact</label><textarea id="problem-summary">${esc(c.problem)}</textarea></div>${field('Source and review rationale','manual-reason')}`,'<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-problem">Save reviewed summary</button>');return;
case'save-problem':setBusy(true);await mutate(`/api/cases/${c.id}/review`,{revision:c.revision,kind:'problem',problem:$('#problem-summary').value,reason:$('#manual-reason').value},'Problem summary saved. Ratings and conditions remain separately reviewed.');return;
case'conditions':conditionsModal();return;
case'save-conditions':{const values={};for(const k of Object.keys(state.rules.conditionLabels)){const v=$('#condition-'+k).value;values[k]=v==='pending'?null:v==='true'}setBusy(true,'Saving qualification review…');await mutate(`/api/cases/${c.id}/review`,{revision:c.revision,kind:'conditions',conditions:values,blocker:$('#blocker').value||null,reason:$('#manual-reason').value},'Qualification conditions saved.');return;}
case'generate-outreach':setBusy(true,'Preparing an editable outreach draft…');await mutate(`/api/cases/${c.id}/outreach`,{revision:c.revision},'Outreach draft saved.');tab='prepare';render();return;
case'save-draft':setBusy(true,'Saving edited draft…');await mutate(`/api/cases/${c.id}/outreach`,{revision:c.revision,operation:'save',subject:$('#saved-subject').value,draft:$('#saved-draft').value},'Edited outreach draft saved.');return;
case'copy-draft':{const text=$('#saved-subject').value+'\n\n'+$('#saved-draft').value;try{await navigator.clipboard.writeText(text);toast('Edited draft copied. Nothing was sent.')}catch{download('CGS-outreach-draft.txt',text);toast('Draft downloaded as text.')}return;}
case'generate-actions':setBusy(true,'Reviewing gaps and next actions…');await mutate(`/api/cases/${c.id}/actions`,{revision:c.revision},'Suggested actions saved.');return;
case'new-task':taskModal();return;
case'suggested-task':if(c.advice.baseRevision!==c.revision)throw new Error('Refresh the suggestions against the current case before creating a task.');taskModal(c.advice.actions[Number(el.dataset.index)]);return;
case'save-task':setBusy(true,'Recording agreed action…');await mutate(`/api/cases/${c.id}/tasks`,{revision:c.revision,title:$('#task-title').value,assignee:$('#task-owner').value,due:$('#task-due').value,side:$('#task-side').value,confirmed:$('#task-confirmed').checked},'Agreed action saved. Scores remain unchanged.');return;
case'toggle-task':setBusy(true);await mutate(`/api/cases/${c.id}/tasks`,{revision:c.revision,operation:'toggle',taskId:el.dataset.id},'Task updated. No score changed automatically.');return;
case'reschedule':{const t=c.tasks.find(t=>t.id===el.dataset.id);modal('Reschedule an agreed action',esc(t.title),`${field('New agreed due date','reschedule-date',t.due,'date')}${field('Reason','reschedule-reason')}`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-reschedule" data-id="${t.id}">Save new date</button>`);return;}
case'save-reschedule':setBusy(true);await mutate(`/api/cases/${c.id}/tasks`,{revision:c.revision,operation:'reschedule',taskId:el.dataset.id,due:$('#reschedule-date').value,reason:$('#reschedule-reason').value},'Action rescheduled.');return;
case'snooze':setBusy(true);await mutate('/api/reminders/snooze',{id:el.dataset.id},'Reminder snoozed for 7 days.');return;
case'pack':packModal();return;
case'review-approval':selected=el.dataset.caseId;packModal(true);return;
case'submit-pack':setBusy(true,'Freezing qualification snapshot…');await mutate(`/api/cases/${c.id}/approval`,{revision:c.revision,operation:'submit'},'Submitted for human review. No CRM update.');return;
case'exception':modal('Request an exception review','Readiness stays unchanged. An authorized human must assess the exception.','<div class="form-field"><label for="exception-reason">Business reason and supporting evidence</label><textarea id="exception-reason"></textarea></div>','<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-exception">Submit exception request</button>');return;
case'save-exception':setBusy(true);await mutate(`/api/cases/${c.id}/approval`,{revision:c.revision,operation:'exception',reason:$('#exception-reason').value},'Exception request saved for human review.');return;
case'approval-decision':setBusy(true,'Recording human decision…');await mutate(`/api/cases/${c.id}/approval`,{revision:c.revision,operation:el.dataset.decision,reason:$('#approval-reason').value},'Human review decision saved. No CRM update.');return;
case'export-pack':{const snapshot=el.dataset.frozen==='yes'?c.approval.snapshot:null;download(`CGS-${c.id}-qualification-pack.html`,`<!doctype html><html lang="en"><meta charset="utf-8"><title>CGS qualification pack</title><style>body{font:14px/1.7 Arial,sans-serif;max-width:820px;margin:40px auto;padding:20px;color:#18343c}h3{margin-top:28px}p{white-space:pre-wrap}.condition{padding:8px;border-bottom:1px solid #ddd}.state{float:right}svg{display:none}.pack-section{border-bottom:1px solid #ddd;padding:12px 0}</style><h1>CGS qualification pack</h1><p>Local prototype · confirmed evidence snapshot · no CRM write</p>${packHTML(c,snapshot)}</html>`,'text/html');toast('Printable qualification pack exported.');return;}
case'export':{const rows=[['Company','Owner','Stage','Readiness','Not ready reason','Q lower','Q upper','Coverage','CGS revenue low USD','CGS revenue high USD','P lower','P upper','Priority'],...state.cases.map(c=>[c.company,c.owner,c.stage,c.result.readiness,state.rules.reasons[c.blocker]||'',c.result.ql,c.result.qu,c.result.coverage,c.revenue?.low??'',c.revenue?.high??'',c.result.pl,c.result.pu,c.result.priority])];download('CGS-work-queue.csv',rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\r\n'),'text/csv');return;}
case'save-mode':setBusy(true);await mutate('/api/config',{mode:$('#mode-setting').value},'Analysis mode saved.');return;
case'save-clock':setBusy(true);await mutate('/api/config',{clock:$('#clock-setting').value,today:$('#clock-date').value},'Clock saved. Reminders recalculated without score deductions.');return;
case'reset':modal('Reset the sample workspace?','This removes imported sources, reviews, tasks and cases from this local database.','<p class="description">The seven original sample cases will be restored. Export any qualification packs you want to keep first.</p>','<button class="btn" data-action="close">Keep changes</button><button class="btn danger" data-action="confirm-reset">Reset local workspace</button>');return;
case'confirm-reset':setBusy(true);await mutate('/api/demo/reset',{confirm:'RESET'},'Sample workspace restored.');go('queue');return;
}}catch(e){if(e.status===409){await refresh();}showError(e)}finally{setBusy(false)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-nav],[data-case],[data-tab]');if(!el||busy)return;if(el.dataset.action){handle(el.dataset.action,el);return}if(el.dataset.nav){close();go(el.dataset.nav);return}if(el.dataset.case){close();openCase(el.dataset.case,el.dataset.tab);return}if(el.dataset.tab){tab=el.dataset.tab;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render()}});
document.addEventListener('change',async e=>{if(e.target.id==='filter'){filter=e.target.value;render()}if(e.target.id==='owner-filter'){owner=e.target.value;render()}if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='text-file'){const file=e.target.files[0];if(file){if(file.size>64000){showError(new Error('Import a plain text file under 64 KB.'));return}const text=await file.text();if(text.length>16000){showError(new Error('The note exceeds 16,000 characters.'));return}$('#note').value=text;$('#source-label').value=file.name}}});
$('#dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
refresh().catch(e=>{$('#app').innerHTML=`<div class="startup-error"><h1>Start the CGS backend to continue.</h1><p>${esc(e.message)}</p><code>python3 server.py --port 8765</code><p>Run this command from the cgs-prototype source folder, then reload.</p><button class="btn" onclick="location.reload()">Reload workspace</button></div>`});
})();
